draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw ancient grain plant
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t), H/2 - 50);
  ctx.stroke();

  // draw quinoa grain
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t), H/2 - 50, 10, 0, 2*Math.PI);
  ctx.fill();

  // draw stick figure farmer
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 + 50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 70);
  ctx.lineTo(W/2 - 100, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 90);
  ctx.lineTo(W/2 - 80, H/2 + 110);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 90);
  ctx.lineTo(W/2 - 120, H/2 + 110);
  ctx.stroke();

  // draw protein symbol
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('P', W/2 + 100 + 20*Math.cos(t), H/2);

  ctx.restore();
}
